def file_name_check(file_name):
    def has_no_more_than_three_digits(file_name):
        return sum(1 for char in file_name if char.isdigit()) <= 3

    def has_exactly_one_dot(file_name):
        return file_name.count('.') == 1

    def has_valid_prefix(file_name):
        segments = file_name.split('.')
        if len(segments) != 2:
            return False
        prefix = segments[0]
        return prefix and prefix[0].isalpha()

    def has_valid_extension(file_name):
        segments = file_name.split('.')
        if len(segments) != 2:
            return False
        extension = segments[1]
        return extension in ['txt', 'exe', 'dll']

    return 'Yes' if all([has_no_more_than_three_digits(file_name),
                         has_exactly_one_dot(file_name),
                         has_valid_prefix(file_name),
                         has_valid_extension(file_name)]) else 'No'
